#include <Arduino.h>
#include <Wire.h>

// User specified pins
#define SDA_PIN 21
#define SCL_PIN 19
#define OLED_ADDR 0x3C
#define I2C_FREQ 400000 // Fast Mode 400kHz

// Command macro
void sendCommand(uint8_t command) {
  Wire.beginTransmission(OLED_ADDR);
  Wire.write(0x00); // Control byte: Co = 0, D/C = 0 (Command)
  Wire.write(command);
  Wire.endTransmission();
}

void initOLED() {
  Wire.begin(SDA_PIN, SCL_PIN, I2C_FREQ);
  
  // Universal Initialization sequence for both SSD1306 and SH1106 (1.3" OLEDs)
  sendCommand(0xAE); // Display OFF
  sendCommand(0xD5); // Set Display Clock Divide Ratio
  sendCommand(0x80); // Default
  sendCommand(0xA8); // Set Multiplex Ratio
  sendCommand(0x3F); // 64MUX (for 128x64)
  sendCommand(0xD3); // Set Display Offset
  sendCommand(0x00); // 0
  sendCommand(0x40); // Set Display Start Line (0)
  sendCommand(0x8D); // Charge Pump Setting
  sendCommand(0x14); // Enable charge pump
  sendCommand(0x20); // Set Memory Addressing Mode
  sendCommand(0x02); // *** PAGE ADDRESSING MODE ***
  sendCommand(0xA1); // Set Segment Re-map (flip horizontal)
  sendCommand(0xC8); // Set COM Output Scan Direction (flip vertical)
  sendCommand(0xDA); // Set COM Pins Hardware Configuration
  sendCommand(0x12); // Alternative COM pin config for 128x64
  sendCommand(0x81); // Set Contrast Control
  sendCommand(0xCF); // High contrast
  sendCommand(0xD9); // Set Pre-charge Period
  sendCommand(0xF1);
  sendCommand(0xDB); // Set VCOMH Deselect Level
  sendCommand(0x40);
  sendCommand(0xA4); // Entire Display ON (resume)
  sendCommand(0xA6); // Normal Display (not inverted)
  sendCommand(0xAF); // Display ON
}

