// Function to draw an image from PROGMEM directly to the screen
void drawImageFromPROGMEM(const uint8_t* image) {
  for (uint8_t page = 0; page < 8; page++) {
    sendCommand(0xB0 + page);
    sendCommand(0x02); // Offset by 2 columns for SH1106 OLEDs
    sendCommand(0x10);
    
    for (int chunk = 0; chunk < 2; chunk++) {
      Wire.beginTransmission(OLED_ADDR);
      Wire.write(0x40); 
      for (int i = 0; i < 64; i++) {
        int bufferIndex = (page * 128) + (chunk * 64) + i;
        Wire.write(pgm_read_byte(&image[bufferIndex]));
      }
      Wire.endTransmission();
    }
  }
}

void setup() {
  Serial.begin(1000000); 
  Serial.setTimeout(100); 
  
  initOLED();
  
  // Show "Hello, World!" splash screen immediately on boot
  drawImageFromPROGMEM(splashScreen);
  
  // Handshake: Tell Python that ESP32 is ready to receive the video stream
  Serial.write('K');
}

uint8_t frameBuffer[1024];
bool findingHeader = true;
uint8_t lastByte = 0x00;

void drawFrame() {
  for (uint8_t page = 0; page < 8; page++) {
    sendCommand(0xB0 + page);
    sendCommand(0x02); // Offset by 2 columns for SH1106 OLEDs
    sendCommand(0x10);
    
    for (int chunk = 0; chunk < 2; chunk++) {
      Wire.beginTransmission(OLED_ADDR);
      Wire.write(0x40); 
      for (int i = 0; i < 64; i++) {
        int bufferIndex = (page * 128) + (chunk * 64) + i;
        Wire.write(frameBuffer[bufferIndex]);
      }
      Wire.endTransmission();
    }
  }
}

void loop() {
  if (Serial.available() > 0) {
    if (findingHeader) {
      uint8_t b = Serial.read();
      if (lastByte == 0xAA && b == 0x55) {
        findingHeader = false; 
      }
      lastByte = b;
    } else {
      int bytesRead = Serial.readBytes((char*)frameBuffer, 1024);
      
      if (bytesRead == 1024) {
        // Once video data arrives, this overwrites the Hello World screen
        drawFrame();
        
        // Handshake: Send 'K' back to request next frame
        Serial.write('K');
      }
      
      findingHeader = true;
      lastByte = 0x00;
    }
  }
}